static int cmp(const void *a, const void *b) {
  return *(int *)a - *(int *)b;
}

static void dfs(int *nums, int n, int *used, int *cur, int depth, int **res, int *size, int **cols) {
  if (depth == n) {
    res[*size] = (int *)malloc(sizeof(int) * n);
    for (int i = 0; i < n; i++) {
      res[*size][i] = cur[i];
    }
    (*cols)[*size] = n;
    (*size)++;
    return;
  }
  for (int i = 0; i < n; i++) {
    if (used[i]) {
      continue;
    }
    if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) {
      continue;
    }
    used[i] = 1;
    cur[depth] = nums[i];
    dfs(nums, n, used, cur, depth + 1, res, size, cols);
    used[i] = 0;
  }
}

int **permuteUnique(int *nums, int numsSize, int *returnSize, int **returnColumnSizes) {
  qsort(nums, numsSize, sizeof(int), cmp);
  int **res = (int **)malloc(sizeof(int *) * 1000);
  *returnColumnSizes = (int *)malloc(sizeof(int) * 1000);
  int *cur = (int *)malloc(sizeof(int) * numsSize);
  int *used = (int *)calloc(numsSize, sizeof(int));
  *returnSize = 0;
  dfs(nums, numsSize, used, cur, 0, res, returnSize, returnColumnSizes);
  free(cur);
  free(used);
  return res;
}

class Solution {
  vector<int> vis;

public:
  void backtrack(vector<int> &nums, vector<vector<int>> &ans, int idx, vector<int> &perm) {
    if (idx == nums.size()) {
      ans.emplace_back(perm);
      return;
    }
    for (int i = 0; i < (int)nums.size(); ++i) {
      if (vis[i] || (i > 0 && nums[i] == nums[i - 1] && !vis[i - 1])) {
        continue;
      }
      perm.emplace_back(nums[i]);
      vis[i] = 1;
      backtrack(nums, ans, idx + 1, perm);
      vis[i] = 0;
      perm.pop_back();
    }
  }

  vector<vector<int>> permuteUnique(vector<int> &nums) {
    vector<vector<int>> ans;
    vector<int> perm;
    vis.resize(nums.size());
    sort(nums.begin(), nums.end());
    backtrack(nums, ans, 0, perm);
    return ans;
  }
};

func permuteUnique(nums []int) [][]int {
	sort.Ints(nums)
	n := len(nums)
	var res [][]int
	var cur []int
	used := make([]bool, n)
	var dfs func(depth int)
	dfs = func(depth int) {
		if depth == n {
			tmp := make([]int, n)
			copy(tmp, cur)
			res = append(res, tmp)
			return
		}
		for i := 0; i < n; i++ {
			if used[i] {
				continue
			}
			if i > 0 && nums[i] == nums[i-1] && !used[i-1] {
				continue
			}
			used[i] = true
			cur = append(cur, nums[i])
			dfs(depth + 1)
			cur = cur[:len(cur)-1]
			used[i] = false
		}
	}
	dfs(0)
	return res
}

class Solution {
  private void backtrack(int[] nums, boolean[] used, List<Integer> cur, List<List<Integer>> res) {
    if (cur.size() == nums.length) {
      res.add(new ArrayList<>(cur));
      return;
    }
    for (int i = 0; i < nums.length; i++) {
      if (used[i]) {
        continue;
      }
      if (i > 0 && nums[i] == nums[i - 1] && !used[i - 1]) {
        continue;
      }
      used[i] = true;
      cur.add(nums[i]);
      backtrack(nums, used, cur, res);
      cur.remove(cur.size() - 1);
      used[i] = false;
    }
  }

  public List<List<Integer>> permuteUnique(int[] nums) {
    Arrays.sort(nums);
    List<List<Integer>> res = new ArrayList<>();
    backtrack(nums, new boolean[nums.length], new ArrayList<>(), res);
    return res;
  }
}

class Solution:
    def permuteUnique(self, nums: List[int]) -> List[List[int]]:
        nums.sort()
        n = len(nums)
        res = []
        cur = []
        used = [False] * n

        def backtrack():
            if len(cur) == n:
                res.append(cur[:])
                return
            for i in range(n):
                if used[i]:
                    continue
                if i > 0 and nums[i] == nums[i - 1] and not used[i - 1]:
                    continue
                used[i] = True
                cur.append(nums[i])
                backtrack()
                cur.pop()
                used[i] = False

        backtrack()
        return res

impl Solution {
  pub fn permute_unique(mut nums: Vec<i32>) -> Vec<Vec<i32>> {
    nums.sort();
    fn backtrack(
      nums: &[i32],
      used: &mut Vec<bool>,
      cur: &mut Vec<i32>,
      res: &mut Vec<Vec<i32>>,
    ) {
      if cur.len() == nums.len() {
        res.push(cur.clone());
        return;
      }
      for i in 0..nums.len() {
        if used[i] {
          continue;
        }
        if i > 0 && nums[i] == nums[i - 1] && !used[i - 1] {
          continue;
        }
        used[i] = true;
        cur.push(nums[i]);
        backtrack(nums, used, cur, res);
        cur.pop();
        used[i] = false;
      }
    }
    let mut res = vec![];
    let mut cur = vec![];
    let mut used = vec![false; nums.len()];
    backtrack(&nums, &mut used, &mut cur, &mut res);
    res
  }
}

const permuteUnique = (nums: number[]): number[][] => {
  nums.sort((a, b) => a - b);
  const n = nums.length;
  const res: number[][] = [];
  const cur: number[] = [];
  const used = new Array(n).fill(false);

  const backtrack = () => {
    if (cur.length === n) {
      res.push([...cur]);
      return;
    }
    for (let i = 0; i < n; i++) {
      if (used[i]) continue;
      if (i > 0 && nums[i] === nums[i - 1] && !used[i - 1]) continue;
      used[i] = true;
      cur.push(nums[i]);
      backtrack();
      cur.pop();
      used[i] = false;
    }
  };

  backtrack();
  return res;
};
